// file-demo.js —— Node.js 文件读写入门
// 运行方式：node file-demo.js（需 package.json 中 "type": "module"，
// 或者把文件命名为 file-demo.mjs）

import { mkdir, writeFile, appendFile, readFile } from 'node:fs/promises';
import { join } from 'node:path';

// 1. 用 path.join 拼路径，跨平台安全（Windows 用反斜杠，Linux 用正斜杠）
const dir = './notes';
const file = join(dir, '2026-10-31.txt');

async function main() {
  // 2. 递归创建目录；已存在时不会报错
  await mkdir(dir, { recursive: true });

  // 3. 写入文件（若已存在会被覆盖），'utf8' 表示按文本处理
  await writeFile(file, '今天学习 Node.js 文件读写\n', 'utf8');

  // 4. 追加内容，不影响已有内容
  await appendFile(file, 'fs/promises 配合 async/await 很好用\n', 'utf8');

  // 5. 读取并指定 utf8，得到字符串而非 Buffer
  const content = await readFile(file, 'utf8');
  console.log('---- 读取结果 ----');
  console.log(content);

  // 6. 做点小加工：统计行数
  const lines = content.trim().split('\n');
  console.log(`一共 ${lines.length} 行`);
}

// 7. 统一的错误兜底：文件权限、磁盘错误都会走到这里
main().catch((err) => {
  console.error('出错了：', err.message);
  process.exit(1);
});

